     1→import { Processor, WorkerHost, OnWorkerEvent } from '@nestjs/bullmq';
     2→import { Logger, BadRequestException } from '@nestjs/common';
     3→import { Job } from 'bullmq';
     4→import { PrismaClient, EventType } from '@repo-pulse/database';
     5→import { EventService } from './event.service';
     6→
     7→interface WebhookEventJob {
     8→  repositoryId: string;
     9→  platform: 'github' | 'gitlab';
    10→  eventType: string;
    11→  payload: Record<string, unknown>;
    12→}
    13→
    14→@Processor('webhook-events')
    15→export class EventProcessor extends WorkerHost {
    16→  private readonly logger = new Logger(EventProcessor.name);
    17→  private prisma: PrismaClient;
    18→
    19→  constructor(private readonly eventService: EventService) {
    20→    super();
    21→    this.prisma = new PrismaClient();
    22→  }
    23→
    24→  async process(job: Job<WebhookEventJob>): Promise<void> {
    25→    const { repositoryId, platform, eventType, payload } = job.data;
    26→
    27→    this.logger.log(`Processing ${eventType} event for repository ${repositoryId}`);
    28→
    29→    try {
    30→      // 检查是否已存在相同 externalId 的事件（防止重复处理）
    31→      const externalId = this.extractExternalId(platform, eventType, payload);
    32→      const existing = await this.eventService.findByExternalId(repositoryId, externalId);
    33→
    34→      if (existing) {
    35→        this.logger.warn(`Event ${externalId} already exists, skipping`);
    36→        return;
    37→      }
    38→
    39→      // 标准化事件数据
    40→      const eventData = this.normalizeEventData(platform, eventType, payload);
    41→
    42→      // 存储事件
    43→      await this.eventService.create({
    44→        repositoryId,
    45→        type: eventData.type,
    46→        action: eventData.action,
    47→        title: eventData.title,
    48→        body: eventData.body,
    49→        author: eventData.author,
    50→        authorAvatar: eventData.authorAvatar,
    51→        externalId,
