import { prisma, Approval, ApprovalStatus, RiskLevel } from '@repo-pulse/database';

export interface CreateApprovalDto {
  eventId: string;
  originalContent?: string;
}

export interface UpdateApprovalDto {
  status: ApprovalStatus;
  editedContent?: string;
  comment?: string;
}

@Injectable()
export class ApprovalService {
  private readonly logger = new Logger(ApprovalService.name);

  /**
   * 获取用户的审批列表
   */
  async getApprovals(
    userId: string,
    options?: {
      status?: ApprovalStatus;
      limit?: number;
      offset?: number;
    },
  ): Promise<{ approvals: Approval[]; total: number }> {
    const where: Record<string, unknown> = {};

    // 查找用户有权限审批的事件
    const userRepos = await prisma.userRepository.findMany({
      where: { userId },
      select: { repositoryId: true },
    });

    const repoIds = userRepos.map((r) => r.repositoryId);

    // 获取用户仓库对应的事件
    const events = await prisma.event.findMany({
      where: { repositoryId: { in: repoIds } },
      select: { id: true },
    });
    const eventIds = events.map((e) => e.id);

    where.eventId = { in: eventIds };

    if (options?.status) {
      where.status = options.status;

import {
  Controller,
  Get,
  Post,
  Param,
  ParseUUIDPipe,
  Query,
  UseGuards,
  Body,
} from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { CurrentUser } from '../auth/decorators/current-user.decorator';
import { ApprovalService, UpdateApprovalDto } from './approval.service';
import type { Approval, ApprovalStatus } from '@repo-pulse/database';

@Controller('approvals')
@UseGuards(AuthGuard('jwt'))
export class ApprovalController {
  constructor(private readonly approvalService: ApprovalService) {}

  /**
   * 获取审批列表
   */
  @Get()
  async getApprovals(
    @CurrentUser() user: { userId: string },
    @Query('status') status?: ApprovalStatus,
    @Query('limit') limit?: string,
    @Query('offset') offset?: string,
  ): Promise<{ approvals: Approval[]; total: number }> {
    return this.approvalService.getApprovals(user.userId, {
      status,
      limit: limit ? parseInt(limit, 10) : undefined,
      offset: offset ? parseInt(offset, 10) : undefined,
    });
  }

  /**
   * 获取待审批数量
   */
  @Get('pending-count')
  async getPendingCount(
    @CurrentUser() user: { userId: string },
  ): Promise<{ count: number }> {
    const count = await this.approvalService.getPendingCount(user.userId);
    return { count };
  }

  /**
   * 获取审批详情
   */
  @Get(':id')
  async getById(
    @Param('id', ParseUUIDPipe) approvalId: string,
  ): Promise<Approval | null> {
    return this.approvalService.getById(approvalId);
  }

  /**
   * 审批通过
   */
  @Post(':id/approve')
  async approve(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) approvalId: string,
    @Body() body: { comment?: string },
  ): Promise<Approval> {
    return this.approvalService.approve(approvalId, user.userId, body.comment);
  }

  /**
   * 审批拒绝
   */
  @Post(':id/reject')
  async reject(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) approvalId: string,
    @Body() body: { comment?: string },
  ): Promise<Approval> {
    return this.approvalService.reject(approvalId, user.userId, body.comment);
  }

  /**
   * 编辑后审批
   */
  @Post(':id/edit')
  async editAndApprove(
    @CurrentUser() user: { userId: string },
    @Param('id', ParseUUIDPipe) approvalId: string,
    @Body() body: { editedContent: string; comment?: string },
  ): Promise<Approval> {
    return this.approvalService.editAndApprove(
      approvalId,
      user.userId,
      body.editedContent,
      body.comment,
    );
  }
}

